/* Detailed operational-action rights for each user. */
(function(){
  const catalog=[
    ['Dashboard',['View Dashboard','View Notifications','Open Quick Actions']],['Business Setting',['Edit Settings','Manage Invoice Template','Edit Invoice Layout','Create Restore Point','Restore Backup','Download Backup']],['List Management',['Add List Value','Edit List Value','Delete List Value','View List History','Search and Filter']],['Customer Master',['View Customer Details','Add Customer','Edit Customer','Delete Customer','Bulk Select','Bulk Delete','View Customer History','Import Customers','Export Customers','Print Customers']],['Vehicle Master',['View Vehicle Details','Add Vehicle','Edit Vehicle','Delete Vehicle','Bulk Select','Bulk Delete','View Service Due','Import Vehicles','Export Vehicles']],['Insurance',['Add Policy','Edit Policy','Delete Policy','View Policy Details','Search and Filter','Share Policy on WhatsApp','Copy Policy Details','Export Policies','Print Policies']],['Staff Master',['View Staff Details','Add Staff','Edit Staff','Delete Staff','Search and Filter','View Salary Calculation','View Staff Documents','Export Staff']],['Staff Attendance',['Mark Attendance','Edit Attendance','View Monthly Matrix','Search and Filter','Export Attendance','Print Attendance']],['Per Job Salary',['View Job Earnings','View Completed Jobs','Record Salary Payment','Search and Filter','Export Payroll','Print Payroll']],['Service Master',['View Service Details','Add Service','Edit Service','Delete Service','Search and Filter','Export Services','Print Services']],['Account Master',['View Account Details','Add Account','Edit Account','View Ledger','Mark Inactive','Search and Filter','Export Accounts','Print Accounts']],['Appointment Booking',['Add Appointment','Edit Appointment','Delete Appointment','Search and Filter','Convert to Job Card','Export Appointments','Print Appointments']],['Job Card',['View Job Details','Add Job Card','Edit Job Card','Receive Payment','Record Due Payment','Search and Filter','Bulk Select','Bulk Delete','Print Invoice','Share WhatsApp','Attach Temporary Files','Change Job Status','View Job History','Delete Job Card']],['Spare Parts',['View Part Details','Add Spare Part','Edit Spare Part','Delete Spare Part','Search and Filter','Bulk Select','Bulk Delete','Stock Adjustment','View Stock History','Import Spare Parts','Export Spare Parts','Print Spare Parts']],['Godown Stock',['Transfer to Main Stock','Edit Part Details','View Transfer History','View Godown Stock','Search and Filter','Stock Adjustment','Export Godown Stock','Print Stock']],['Spare Parts Sale',['View Sale Details','Add Sale','Edit Sale','Receive Payment','Search and Filter','Bulk Select','Bulk Delete','Print Invoice','Share WhatsApp','Delete Sale','Export Sales']],['Purchase',['View Purchase Details','Add Purchase','Edit Purchase','Receive Stock','Receive to Godown','Receive to Main Stock','Search and Filter','Approve Purchase','Bulk Select','Bulk Delete','Delete Purchase','Export Purchases','Print Purchases']],['Vehicle Service Reminders',['Schedule Service','Edit Due Date','Search and Filter','Send WhatsApp Reminder','Mark Complete','Export Reminders']],['AMC Management / Reminder',['Add AMC Plan','Edit AMC Plan','Renew AMC','Search and Filter','Send AMC Reminder','View AMC Expiry','Export AMC Plans','Export AMC Reminders']],['Payment Details',['View Statement','Receive Customer Payment','Send Due Reminder','Search and Filter','View Payment Audit','Export Payments','Print Payments']],['Expenses',['View Expense Details','Add Expense','Edit Expense','Delete Expense','Search and Filter','Bulk Select','Bulk Delete','Print Expense List','Export Expenses','Record Salary Advance','Record Salary Payment']],['Reports',['View Reports','Search and Filter','Export Report','Print Report','View Sales Report','View Purchase Report','View GST Annual Report','Export GST Annual Report','View Due Report','View Profit Report','View Collection Report']],['Staff Salary Report',['View Salary Report','Filter Staff / Month','Search and Filter','Export Salary Report','Print Salary Report']],['Spare Parts Movement Report',['View Movement Report','Filter Part / Date','Search and Filter','Export Movement Report','Print Movement Report']],['Users',['View User Details','Add User','Edit User','Search and Filter','Set Password','Assign Module Permissions','Assign Action Rights','Deactivate User','Export Users']],['Audit Logs',['View Audit Logs','View Audit Details','Search and Filter','Export Audit Logs','Print Audit Logs']]
  ];
  const blank=()=>Object.fromEntries(catalog.map(([module,rights])=>[module,Object.fromEntries(rights.map(right=>[right,false]))]));
  function roleActionDefaults(){return blank()}
  function rows(restrictions){return catalog.flatMap(([module,rights])=>rights.map((right,index)=>`<tr><td>${index===0?esc(module):''}</td><td>${esc(right)}</td><td><input type="checkbox" data-user-action-module="${esc(module)}" data-user-action-right="${esc(right)}" ${restrictions?.[module]?.[right]?'checked':''} aria-label="Not allowed: ${esc(right)}"></td></tr>`)).join('')}
  function grid(saved,role){const restrictions=saved||roleActionDefaults(role);return `<details class="userActionPermissionPanel" open><summary>SUB-ACTION RESTRICTIONS</summary><p class="roleActionTemplate">Main module permissions control normal access for <strong>${esc(role||'User')}</strong>. Tick <strong>Not Allowed</strong> only to block a particular sub-action. <strong>A sub-action can never grant a right that the main module has not granted.</strong></p><div class="modulePermissionQuickControls"><button type="button" class="btn secondary small" data-apply-role-template>Clear All Sub-Action Restrictions</button></div><div class="tablewrap"><table><thead><tr><th>Module</th><th>Action</th><th>Not Allowed</th></tr></thead><tbody>${rows(restrictions)}</tbody></table></div></details>`}
  function read(container){const output=blank();for(const checkbox of container.querySelectorAll('[data-user-action-module]'))output[checkbox.dataset.userActionModule][checkbox.dataset.userActionRight]=checkbox.checked;return output}
  const editUserWithBasePermissions=editRecord;
  editRecord=function(key,id,initial={}){
    editUserWithBasePermissions(key,id,initial);
    if(key!=='users')return;
    const form=$('#recordForm'),record=id?find('users',id):null;
    if(!form||form.querySelector('.userActionPermissionPanel'))return;
    const roleSelect=form.elements.role;
    const holder=document.createElement('div');holder.innerHTML=grid(record?.actionRestrictions,roleSelect?.value);form.querySelector('.formbody').appendChild(holder.firstElementChild);
    const panel=form.querySelector('.userActionPermissionPanel');
    const applyRoleTemplate=()=>{const role=roleSelect?.value||'User',restrictions=roleActionDefaults(role);panel.querySelector('tbody').innerHTML=rows(restrictions);panel.querySelector('.roleActionTemplate').innerHTML=`Main module permissions control normal access for <strong>${esc(role)}</strong>. Tick <strong>Not Allowed</strong> only to block a particular sub-action. <strong>A sub-action can never grant a right that the main module has not granted.</strong>`;};
    panel.querySelector('[data-apply-role-template]').onclick=applyRoleTemplate;
    roleSelect?.addEventListener('change',applyRoleTemplate);
    const saveBaseUser=form.onsubmit;
    form.onsubmit=async event=>{
      const userName=form.elements.username?.value;
      const permissions=read(form);
      await saveBaseUser.call(form,event);
      const user=(db.users||[]).find(item=>item.username===userName);
      if(!user)return;
      user.actionRestrictions=permissions;
      audit('Update',`${user.username} sub-action restrictions updated`);
      save('User sub-action restrictions saved');
      render();
    };
  };
})();
